<div class="toolbar"><form class="filters" method="get" data-directory-filter><label class="search-field"><?= icon('search',18) ?><input name="q" value="<?= e($q) ?>" placeholder="Nombre, documento o código" aria-label="Buscar paciente"></label><select name="status" aria-label="Estado"><option value="">Todos los estados</option><option value="active"<?= selected($status,'active') ?>>Activos</option><option value="inactive"<?= selected($status,'inactive') ?>>Inactivos</option></select><button class="button secondary">Buscar</button><a class="button secondary" data-context-reset href="<?= e(url('/admin/patients')) ?>">Limpiar filtros</a></form><a class="button" href="<?= e(\App\Services\WorkspaceContext::url('/admin/patients',['new'=>1],['edit','view'])) ?>"><?= icon('plus',18) ?> Nuevo paciente</a></div>
<?php if(isset($_GET['new']) || isset($_GET['edit']) || ($error && $_SERVER['REQUEST_METHOD']==='POST')): $p=$error ? $_POST:($patient ?? []); ?><section class="panel form-panel"><h2><?= empty($p['id']) ? 'Registrar paciente':'Editar paciente' ?></h2><form method="post" class="form-grid" data-loading><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)($p['id'] ?? 0) ?>"><?php field('first_name','Nombres',$p['first_name'] ?? ''); field('last_name','Apellidos',$p['last_name'] ?? ''); field('document','Documento de identificación',$p['document'] ?? ''); field('birth_date','Fecha de nacimiento',$p['birth_date'] ?? '','date',false); field('phone','Teléfono',$p['phone'] ?? '','tel'); field('email','Correo electrónico',$p['email'] ?? '','email',false); field('address','Dirección',$p['address'] ?? '','text',false); field('emergency_contact','Contacto de emergencia',$p['emergency_contact'] ?? '','text',false); choose('status','Estado',['active'=>'Activo','inactive'=>'Inactivo'],$p['status'] ?? 'active'); ?><div class="full actions"><button class="button">Guardar paciente</button><a class="button secondary" href="<?= e(\App\Services\WorkspaceContext::url('/admin/patients',[],['new','edit','view'])) ?>">Volver</a></div></form></section><?php endif; ?>
<?php if(isset($_GET['view']) && $patient): ?><section class="panel patient-summary"><div><span class="eyebrow"><?= e($patient['code']) ?></span><h2><?= e($patient['first_name'].' '.$patient['last_name']) ?></h2><p><?= e($patient['phone']) ?> · <?= e($patient['email']) ?></p><p>Documento: <?= e($patient['document']) ?> · Nacimiento: <?= e($patient['birth_date'] ?: 'No registrado') ?></p><?= badge($patient['status']) ?></div><div class="actions"><a class="button secondary" href="<?= e(\App\Services\WorkspaceContext::url('/admin/patients',['edit'=>$patient['id']],['new','view'])) ?>">Editar</a><?php if(can('clinical')): ?><a class="button" href="<?= e(url('/admin/clinical?patient_id='.$patient['id'])) ?>">Historia clínica</a><a class="button secondary" href="<?= e(url('/admin/odontogram?patient_id='.$patient['id'])) ?>">Odontograma</a><?php endif; ?></div></section><?php endif; ?>
<section class="panel" id="patient-directory"><div class="panel-heading"><h2>Directorio de pacientes</h2><span class="muted"><?= (int)$count ?> registros</span></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabla de registros"><table><thead><tr><th>Paciente</th><th>Código</th><th>Documento</th><th>Contacto</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($rows as $p): ?><tr><td><div class="person-cell"><span class="avatar soft"><?= e(mb_substr($p['first_name'],0,1)) ?></span><strong><?= e($p['first_name'].' '.$p['last_name']) ?></strong></div></td><td><?= e($p['code']) ?></td><td><?= e($p['document']) ?></td><td><?= e($p['phone']) ?><small><?= e($p['email']) ?></small></td><td><?= badge($p['status']) ?></td><td><a class="table-link" href="<?= e(\App\Services\WorkspaceContext::url('/admin/patients',['view'=>$p['id']],['new','edit'])) ?>">Ver ficha</a> <a class="table-link" href="<?= e(\App\Services\WorkspaceContext::url('/admin/patients',['edit'=>$p['id']],['new','view'])) ?>">Editar</a></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">No hay pacientes con estos filtros. Registra el primero.</td></tr><?php endif; ?></tbody></table></div><nav class="pagination" aria-label="Páginas de pacientes"><?php for($i=1;$i<=ceil($count/12);$i++): ?><a <?= $i===$page ? 'aria-current="page"':'' ?> href="<?= e(url('/admin/patients?'.http_build_query(['q'=>$q,'status'=>$status,'page'=>$i]))) ?>"><?= $i ?></a><?php endfor; ?></nav></section>
